import { format, endOfDay, isValid, startOfDay } from 'date-fns';
import { useEffect, useMemo, useState } from 'react';

import type { TimeDetails } from '../../../core/types/time.js';
import { parseTime } from '../../../core/utils/timeParser.js';
import type { DatePickerProps } from '../DatePicker.js';

const DATE_FORMAT = 'yyyy-MM-dd';

export type UseDatepickerProps = Pick<
  DatePickerProps,
  'value' | 'onChange' | 'showTime' | 'fillUpTime' | 'precision'
>;

/**
 * Forces the time component of timeDetails to be 00:00:00 if 'day-start'
 * or 23:59:59 if 'day-end'
 */
function flattenTime(
  timeDetails: TimeDetails | null,
  fillUpTime: boolean,
): TimeDetails | null {
  if (!timeDetails) {
    return null;
  }

  // truncate the time
  if (timeDetails.type === 'iso8601') {
    const normalizedDate = fillUpTime
      ? endOfDay(timeDetails.date)
      : startOfDay(timeDetails.date);

    return {
      normalized: normalizedDate.toISOString(),
      date: normalizedDate,
      type: 'iso8601',
    };
  }

  return timeDetails;
}

/** Returns a display string of the given details using current display format.*/
function formatTime(
  details: TimeDetails | null,
  displayFormat: string,
): string | null {
  if (!details) {
    return null;
  }

  switch (details.type) {
    case 'expression':
      return details.normalized;
    case 'iso8601':
      return format(details.date, displayFormat);
    default:
      // Should never happen unless timeparser was extended
      throw new Error(`Unsupported timeparser type '${details.type}'`);
  }
}

/** Custom Datepicker hook.
 * The hook calls on change with any valid parsed date.
 * It calls onChange with null if the input is cleared.
 * It does not call onChange with any value if the date could not be parsed.
 */
export function useDatepicker({
  value,
  showTime,
  fillUpTime,
  onChange,
  precision,
}: UseDatepickerProps) {
  // Format used to display a date in the input field
  const displayFormat = useMemo(
    () =>
      showTime
        ? `${DATE_FORMAT} HH:mm${precision === 'seconds' ? ':ss' : ''}`
        : DATE_FORMAT,
    [precision, showTime],
  );

  // The value of the text input associated with the datepicker.
  // This is not the current value of the datepicker while typing
  // therefore we need to control the state of the input separately from the value
  const [inputValue, setInputValue] = useState('');

  // Update the parsed time whenever the value changes
  const parsedTime = useMemo(() => parseTime(value), [value]);

  // Value as ISO string, used to pass to the calendar
  const calendarValue = useMemo(
    () => parsedTime?.date?.toISOString() ?? null,
    [parsedTime],
  );

  // Set the input value accordingly when one of the dependencies changes
  useEffect(() => {
    const newDisplayValue = formatTime(parsedTime, displayFormat);
    setInputValue(newDisplayValue ?? '');
  }, [displayFormat, parsedTime]);

  /** Callback when the input value changes */
  function onInputValueChange(value: string) {
    setInputValue(value);
  }

  /** Callback when the calendar value changes */
  function onCalendarValueChange(date: string | null) {
    const newParsedTime = parseTime(date);
    /* If the datepicker is used within the timeframe selector, the new time has to be flattened, but if used standalone,
    the initial time should be preserved, so the flattening should only be done if the fillUpTime prop is actually set */
    const newTime =
      fillUpTime === undefined
        ? newParsedTime
        : flattenTime(newParsedTime, fillUpTime);
    changeValue(newTime);
  }

  /** Callback used for parsing, validating and applying the new value. */
  function validateAndApplyValue() {
    const newTimeDetails = parseTime(inputValue);
    const inputValueIsValidDate =
      !inputValue || (newTimeDetails !== null && isValid(newTimeDetails.date));

    if (inputValueIsValidDate) {
      changeValue(newTimeDetails);
    }
  }

  /** Handle calendar value changes, input blur or key down events. */
  function changeValue(newParsedTime: TimeDetails | null): void {
    const formattedTime = formatTime(newParsedTime, displayFormat) ?? '';
    setInputValue(formattedTime);
    onChange({
      value: newParsedTime?.normalized ?? null,
      details: newParsedTime,
      displayValue: formattedTime,
    });
  }

  return {
    calendarValue,
    inputValue,
    onInputValueChange,
    /** Handles whenever the value was changed using the Calendar component. */
    onCalendarValueChange,
    /** Handles submitted value change. */
    validateAndApplyValue,
  };
}
